/** Prefixes used by dynamic labels (dates, counters and customer names). */
const PARTIAL_TRANSLATIONS: [string, string][] = [
  ['Devise du storefront Apple : ', 'Apple storefront currency: '],
  ['L’email n’a pas pu être remis à ', 'The email could not be delivered to '],
  ['Accès conservé jusqu’au ', 'Access kept until '],
  ['Votre accès reste ouvert jusqu’au ', 'Your access stays open until '],
  ['Effective le ', 'Effective on '],
  ['Relancer ', 'Follow up with '],
];

export function localizeText(locale: MobileLocale, value: string): string {
  if (locale === 'fr') return value;
  const direct = TEXT_TRANSLATIONS[value];
  if (direct) return direct;
  for (const [pattern, translate] of PATTERN_TRANSLATIONS) {
    const match = value.match(pattern);
    if (match) return translate(match);
  }
  for (const [from, to] of PARTIAL_TRANSLATIONS) {
    if (value.startsWith(from)) return `${to}${value.slice(from.length)}`;
  }
  return value;
}

export function localizeNode(locale: MobileLocale, node: React.ReactNode): React.ReactNode {
  if (typeof node === 'string') return localizeText(locale, node);
  if (Array.isArray(node)) return node.map((part, index) => React.createElement(React.Fragment, { key: index }, localizeNode(locale, part)));
  return node;
}

const LocaleContext = React.createContext<MobileLocale>('fr');

export function MobileLocaleProvider({ locale, children }: { locale: MobileLocale; children: React.ReactNode }) {
  return React.createElement(LocaleContext.Provider, { value: locale }, children);
}

export function useMobileLocale(): MobileLocale {
  return React.useContext(LocaleContext);
}

export function mobileLocale(session: Pick<SessionDTO, 'user'> | null | undefined): MobileLocale {
  return session?.user.locale === 'en' ? 'en' : 'fr';
}

export function deviceLocale(): MobileLocale {
  try { return Intl.DateTimeFormat().resolvedOptions().locale.toLowerCase().startsWith('en') ? 'en' : 'fr'; }
  catch { return 'fr'; }
}


export function copy(locale: MobileLocale, key: MobileCopyKey): string {
  return DICTIONARY[locale][key];
}
